// components/TitlesTable.tsx (Client Component)
'use client';

import { useTransition } from 'react';
import { useFormState } from 'react-dom';
import { deleteTitle } from '@/app/actions/titles';

interface TitleRowProps {
  title: { id: number; title: string };
  onDelete: () => void;
}

function TitleRow({ title, onDelete }: TitleRowProps) {
  const [state, formAction] = useFormState(deleteTitle, null);
  const [isPending, startTransition] = useTransition();

  return (
    <tr>
      <td>{title.title}</td>
      <td>
        <form action={formAction}>
          <input type="hidden" name="id" value={title.id} />
          <button
            type="submit"
            disabled={isPending}
            className="text-red-600 hover:text-red-800"
          >
            {isPending ? 'Deleting...' : 'Delete'}
          </button>
        </form>
        {state?.error && <p className="text-red-500">{state.error}</p>}
      </td>
    </tr>
  );
}
